    # that results from a KeyboardInterrupt cancelling the awaiting task).
    await asyncio.gather(*running)
except BaseException:
    # Reached when a job raised, or when this coroutine was cancelled (e.g.
    # asyncio.run() cancelling the main task after a KeyboardInterrupt). In
    # every case, make sure no job is left running without a chance to clean
    # up: cancel everything still pending and then wait for all of the jobs
    # to fully finish -- including any cleanup code they run in finally
    # blocks or CancelledError handlers, even if that cleanup awaits.
    for t in running:
        if not t.done():
            t.cancel()
    # While we drain the jobs, further cancellations may be delivered to us
    # (asyncio.run keeps requesting cancellation during shutdown, and Ctrl+C
    # may be pressed again). Absorb them and keep waiting until every job is
    # genuinely done, so cleanup -- sync or async -- runs to completion.
    while True:
        try:
            await asyncio.gather(*running, return_exceptions=True)
            break
        except asyncio.CancelledError:
            # Re-request cancellation of anything still running and keep
            # waiting; do not abandon the jobs mid-cleanup.
            for t in running:
                if not t.done():
                    t.cancel()
            continue
    raise

